// Package redactable provides an interface for redacting sensitive information from specifications.
package redactable

import "github.com/cosi-project/runtime/pkg/resource"

// Spec is implemented by the resource specs which know how to redact the sensitive values they carry.
//
// Implementations are generated by the redactgen tool (tools/redactgen): mark the spec with the
// //redactgen:gen comment, and mark the sensitive fields (including the ones in the nested structs)
// with the `redact:"replace"` struct tag.
//
// The methods are implemented on a pointer to the spec, as the only way to reach the spec of a
// resource generically is [resource.Resource.Spec], which hands out a pointer to it. RedactSecrets
// mutates the spec in place, so the caller is responsible for copying the resource first.
type Spec interface {
	// HasSecrets reports whether the spec carries any sensitive value at the moment.
	//
	// It takes the metadata because for some resources what counts as a secret depends on the ID.
	HasSecrets(md resource.Metadata) bool
	// RedactSecrets redacts the sensitive values of the spec in place.
	//
	// It is only called when HasSecrets reported true for the same metadata.
	RedactSecrets(md resource.Metadata)
}

// SpecPtr constrains PT to be a pointer to the spec T which knows how to redact the sensitive values it carries.
//
// The redaction methods are implemented on the pointer to the spec, so generic code can only reach them
// through a second type parameter constrained by SpecPtr.
type SpecPtr[T any] interface {
	*T
	Spec
	DeepCopy() T
}

// Redact returns a copy of the spec with the sensitive values redacted, or the spec itself if it carries none.
//
// When called from generic code where T is a type parameter, PT has to be passed explicitly
// (Redact[T, PT]), as the method set of *T is empty for a type parameter T.
func Redact[T any, PT SpecPtr[T]](spec T, md resource.Metadata) T {
	if !PT(&spec).HasSecrets(md) {
		return spec
	}

	spec = PT(&spec).DeepCopy()
	PT(&spec).RedactSecrets(md)

	return spec
}
